using System.Text.Json;
namespace Reforged.Server;
public sealed record RuntimeStartupShutdownSmokeReport(bool Passed,IReadOnlyList<string> Checks){public string ToJson()=>JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true});public static RuntimeStartupShutdownSmokeReport Run(){var c=new List<string>();var s=new RuntimeStartupShutdownService([new("configuration-load",10,true,true,false),new("catalog-load",20,true,true,false),new("world-state-load",30,true,true,false),new("timer-event-restore",40,true,true,false),new("admission-stop",50,true,false,true),new("save-coordination",60,true,false,true),new("logging-close",70,false,false,true)]);var seen=new List<RuntimeLifecycleAction>();var start=s.Start("boot-1",x=>{seen.Add(x);return true;});if(!start.Success||!s.AdmissionsOpen||start.Actions.Select(x=>x.StepId).SequenceEqual(["configuration-load","catalog-load","world-state-load","timer-event-restore"])==false)c.Add("startup-order");var stop=s.Stop("stop-1",x=>{seen.Add(x);return true;});if(!stop.Success||s.AdmissionsOpen||stop.Actions.Select(x=>x.StepId).SequenceEqual(["logging-close","save-coordination","admission-stop"])==false)c.Add("shutdown-reverse-order");var fail=new RuntimeStartupShutdownService([new("required",1,true,true,false)]).Start("boot-2",_=>false);if(fail.Success||fail.Phase!=RuntimeLifecyclePhase.Failed)c.Add("required-failure");c.AddRange(s.ValidateState());return new(c.Count==0,c);}}
